      tags: { type: "array" },
      includeTags: { type: "array" },
      excludeTags: { type: "array" },
      key: str,
      name: str,
      nodeName: str,
      kind: str,
      type: str,
      mode: str,
      amplitude: num,
      height: num,
      amount: num,
      previewDepth: num,
      previewAsSlab: bool,
      previewRoughness: num,
      depth: num,
      roughness: num,
      frequency: num,
      octaves: num,
