      if (!toProperty || !isMotionAnimatableProperty(toProperty)) {
        return fail(
          `Unsupported target property: ${String(args.toProperty)}`,
          "INVALID_PARAMS",
        );
      }
      const clipboard = copyMotionPropertyKeyframes(layer.keyframes, fromProperty);
